INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist UDP ein verbindungsloses Protokoll?', 2, '[{"text": "Ja", "correct": true, "because": "UDP etabliert keine Verbindung vor der Datenübertragung"}, {"text": "Nein", "correct": false, "because": "Verbindungslosigkeit ist eine Kernfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Bietet UDP eine Garantie für die Zustellung von Daten?', 2, '[{"text": "Nein", "correct": true, "because": "UDP hat keine Zustellungsbestätigung"}, {"text": "Ja", "correct": false, "because": "Das macht TCP, nicht UDP"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird UDP häufig für Video-Streaming verwendet?', 2, '[{"text": "Ja", "correct": true, "because": "UDP ist schnell und akzeptiert Paketverlust bei Echtzeitanwendungen"}, {"text": "Nein", "correct": false, "because": "UDP ist ideal für Streaming"}]'),
('00000000-0000-0000-0000-000000000000', 'Enthält ein UDP-Header Informationen zur Fehlerkorrektur?', 2, '[{"text": "Nein", "correct": true, "because": "UDP hat keine Fehlerkorrektur, nur eine Prüfsumme"}, {"text": "Ja", "correct": false, "because": "Fehlerkorrektur fehlt bei UDP"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann UDP Pakete in beliebiger Reihenfolge anliefern?', 2, '[{"text": "Ja", "correct": true, "because": "UDP garantiert keine Reihenfolge"}, {"text": "Nein", "correct": false, "because": "Reihenfolge ist nicht gesichert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schicht des OSI-Modells verwendet UDP?', 2, '[{"text": "Transportschicht", "correct": true, "because": "UDP ist ein Transportprotokoll"}, {"text": "Netzwerkschicht", "correct": false, "because": "Das wäre IP"}, {"text": "Anwendungsschicht", "correct": false, "because": "Das wäre z. B. HTTP"}]'),
('00000000-0000-0000-0000-000000000000', 'Warum wird UDP für Anwendungen wie DNS-Abfragen bevorzugt?', 3, '[{"text": "Geringer Overhead und hohe Geschwindigkeit", "correct": true, "because": "UDP ist einfach und schnell"}, {"text": "Garantierte Zustellung", "correct": false, "because": "UDP garantiert nichts"}, {"text": "Fehlerkorrektur", "correct": false, "because": "UDP korrigiert keine Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Größe hat der UDP-Header?', 2, '[{"text": "8 Bytes", "correct": true, "because": "UDP-Header hat 4 Felder à 2 Bytes"}, {"text": "20 Bytes", "correct": false, "because": "Das ist der TCP-Header"}, {"text": "32 Bytes", "correct": false, "because": "Zu groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung nutzt UDP typischerweise?', 2, '[{"text": "Voice over IP (VoIP)", "correct": true, "because": "Echtzeit und Geschwindigkeit sind entscheidend"}, {"text": "Dateiübertragung (FTP)", "correct": false, "because": "FTP nutzt TCP"}, {"text": "E-Mail (SMTP)", "correct": false, "because": "SMTP nutzt TCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Was fehlt UDP im Vergleich zu TCP?', 2, '[{"text": "Flusskontrolle", "correct": true, "because": "UDP hat keine Fluss- oder Fehlerkontrolle"}, {"text": "Portnummern", "correct": false, "because": "UDP hat Portnummern"}, {"text": "Prüfsumme", "correct": false, "because": "UDP hat eine Prüfsumme"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat UDP?', 4, '[{"text": "Verbindungslos", "correct": true, "because": "Keine Verbindung wird aufgebaut"}, {"text": "Niedriger Overhead", "correct": true, "because": "Nur 8 Bytes Header"}, {"text": "Garantierte Reihenfolge", "correct": false, "because": "Reihenfolge nicht gesichert"}, {"text": "Schnelle Übertragung", "correct": true, "because": "Keine Bestätigungen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Felder enthält ein UDP-Header?', 3, '[{"text": "Quellport", "correct": true, "because": "Identifiziert die Quelle"}, {"text": "Zielport", "correct": true, "because": "Identifiziert das Ziel"}, {"text": "Prüfsumme", "correct": true, "because": "Optional zur Fehlererkennung"}, {"text": "Sequenznummer", "correct": false, "because": "Fehlt bei UDP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von UDP?', 4, '[{"text": "Video-Streaming", "correct": true, "because": "Toleranz gegenüber Paketverlust"}, {"text": "Online-Gaming", "correct": true, "because": "Echtzeit wichtig"}, {"text": "Dateiübertragung", "correct": false, "because": "Erfordert Zuverlässigkeit"}, {"text": "DNS-Abfragen", "correct": true, "because": "Schnelle, einfache Anfragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat UDP?', 3, '[{"text": "Keine Zustellungsgarantie", "correct": true, "because": "Pakete können verloren gehen"}, {"text": "Keine Reihenfolge", "correct": true, "because": "Anwendung muss dies handhaben"}, {"text": "Hoher Overhead", "correct": false, "because": "Overhead ist niedrig"}, {"text": "Datenverlust möglich", "correct": true, "because": "Keine Wiederholung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen über UDP sind korrekt?', 3, '[{"text": "Geeignet für Echtzeitanwendungen", "correct": true, "because": "Geschwindigkeit ist entscheidend"}, {"text": "Nutzt einen einfachen Header", "correct": true, "because": "Nur 8 Bytes"}, {"text": "Bietet Flusskontrolle", "correct": false, "because": "Fehlt bei UDP"}, {"text": "Verbindungslos", "correct": true, "because": "Keine Sitzung erforderlich"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) UDP ist schneller als TCP. b) UDP garantiert die Reihenfolge der Pakete.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "UDP ist schneller, keine Reihenfolge"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) UDP hat einen Header von 8 Bytes. b) UDP ist für Dateiübertragungen ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "8 Bytes ja, Dateien brauchen TCP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) UDP wird in der Transportschicht verwendet. b) UDP bietet Fehlerkorrektur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Transportschicht ja, Fehlerkorrektur nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) UDP ist für VoIP geeignet. b) UDP hat eine Prüfsumme im Header.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "VoIP nutzt UDP, Prüfsumme ist enthalten"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) UDP hat keinen Handshake. b) UDP ist langsamer als TCP wegen der Fehlerprüfung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Handshake ja, UDP ist schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

